Set arrIterObj = arr.%GetIterator()
set last = ""
set index =0

while arrIterObj.%GetNext(.key, .value){
	Set arrValObj = value.%GetIterator()	 
    while arrValObj.%GetNext(.key, .value) {
	    if (key = "lastAsserted"){	
	       set t1 = value
	       if (last=""){
	       	set t2 = value		       
	       }else{
		    set t2 = last
		   }
		   set result=$select(t1]t2:1, t1=t2:0, 1:-1)
		   $$$TRACE(t1_"***"_t2_"*****"_result)
		   if (result=-1){
			   set last = t2				   
		   }elseif(result=1){
			   set last = t1
		   }else{
			   set last = t1
		   }       	  		
	    }
    }
}

set count = "0"
Set arrIterObj = arr.%GetIterator()
while arrIterObj.%GetNext(.key, .value){
	set ind = $INCREMENT(index)
	Set arrValObj = value.%GetIterator()	 
    while arrValObj.%GetNext(.key, .value) {
	    if (key = "lastAsserted"){
		    $$$TRACE(value_"**"_last)	
	    	if (value=last){			    	
		    	set count = ind
		    	break
		    }
	    }
    }
}
$$$TRACE(" Last: "_last_" Index : "_count)
Quit count

