		  				set nameObj.middle = value.middle
		  				$$$TRACE("LastName: ["_value.last_"] FirstName: ["_value.first_"] MiddleName: ["_value.middle_"]")    			
		  				set hieDataNamesObj = ##class(IHC.ITF.Service.HieDataNames).%New()
		  				set hieDataNamesObj.name = nameObj
		  				do dataObj.names.SetAt(hieDataNamesObj,index)
	  				}
	    		}		  
    		}
  		}
    }

	 $$$TRACE(" Inside the method - parseMaidenNames ")

	set namesArr = (consumedObj.%Get("data")).%Get("custom.maidenname")
    $$$TRACE("  namesArr: "_namesArr)  	
    set index = 0

    if ($IsObject(namesArr)){
	    set lastUpdated = ..getIndexLastUpdated(namesArr)    	
  		Set arrIterObj = namesArr.%GetIterator()
  		while arrIterObj.%GetNext(.key, .value) {
	  		//$$$TRACE("arrIterObj:::  key: "_key_" Value: "_value)
	  		if (key=(lastUpdated-1)){
	  			Set arrValObj = value.%GetIterator()	 
	    		while arrValObj.%GetNext(.key, .value) {		  		
	  				if (key = "custom.maidenname"){		  		
	  			    	set result = $INCREMENT(index)		  			
    			 		set nameObj = ##class(IHC.ITF.Service.name).%New()
		  				set nameObj.last = value.last
		  				set nameObj.first = value.first
		  				set nameObj.middle = value.middle
		  				$$$TRACE("LastName: ["_value.last_"] FirstName: ["_value.first_"] MiddleName: ["_value.middle_"]")  

		  				set hieDataNamesObj = ##class(IHC.ITF.Service.HieDataCustomMaidennames).%New()
		  				set hieDataNamesObj.customMaidennames = nameObj
		  				do dataObj.hieDataCustomMaidennames.SetAt(hieDataNamesObj,index)
	  				}
	    		}		  
    		}
  		}
    }


	$$$TRACE(" Inside the method - parseAlternateIdentifiers ")

	set altIdArr = (consumedObj.%Get("data")).%Get("alternateIdentifiers")
    $$$TRACE("  altIdArr: "_altIdArr)  	
    set index = 0  

    if ($IsObject(altIdArr)){ 
    	//set lastUpdated = ..getIndexLastUpdated(altIdArr)     
  		Set arrIterObj = altIdArr.%GetIterator()
  		while arrIterObj.%GetNext(.key, .value) {
	  		//	$$$TRACE("arrIterObj:::  key: "_key_" Value: "_value)
	  		//if (key=(lastUpdated-1)){
	  			Set arrValObj = value.%GetIterator()	 
	    		while arrValObj.%GetNext(.key, .value) {			    
	  				if (key = "alternateIdentifiers"){		  		
		  				set result = $INCREMENT(index)		  		
		  				$$$TRACE("Type: "_value.type_" Value: "_value.value_" Issuer: "_value.issuer)    			
    					set altIdObj = ##class(IHC.ITF.Service.alternateIdentifiers).%New()
		  				set altIdObj.type = value.type
		  				set altIdObj.value = value.value
		  				set altIdObj.issuer = value.issuer	
		  				set hieDataAltIdObj = ##class(IHC.ITF.Service.HieDataAlternateIdentifiers).%New()
		  				set hieDataAltIdObj.alternateIdentifiers = altIdObj
		  				do dataObj.alternateIdentifiers.SetAt(hieDataAltIdObj,index)
	  				}
	    		}		  
    		//}
  		}
    }

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
